import{_ as l,a0 as p,w as d,s as o,I as t,x as a,a1 as e,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Linux 如何设置密码复杂度？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 如何设置密码复杂度？ | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 如何设置密码复杂度？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 如何设置密码复杂度？ | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20190513 How To Set Password Complexity On Linux","title":"Linux 如何设置密码复杂度？","tag":"201912","desc":""},"relativePath":"201912/20190513 How To Set Password Complexity On Linux.md","filePath":"[post].md"}'),h={name:"201912/20190513 How To Set Password Complexity On Linux.md"};function c(u,s,g,k,b,m){const i=p("Link");return d(),o("div",null,[s[21]||(s[21]=t("h1",{id:"linux-如何设置密码复杂度",tabindex:"-1"},[a("Linux 如何设置密码复杂度？ "),t("a",{class:"header-anchor",href:"#linux-如何设置密码复杂度","aria-label":"Permalink to “Linux 如何设置密码复杂度？”"},"​")],-1)),t("p",null,[s[1]||(s[1]=a("对于 Linux 系统管理员来说，用户管理是最重要的事之一。这涉及到很多因素，实现强密码策略是用户管理的其中一个方面。移步后面的 URL 查看如何 ",-1)),e(i,{href:"https://www.2daygeek.com/5-ways-to-generate-a-random-strong-password-in-linux-terminal/"},{default:n(()=>[...s[0]||(s[0]=[a("在 Linux 上生成一个强密码",-1)])]),_:1}),s[2]||(s[2]=a("。它会限制系统未授权的用户的访问。",-1))]),t("p",null,[s[4]||(s[4]=a("所有人都知道 Linux 的默认策略很安全，然而我们还是要做一些微调，这样才更安全。弱密码有安全隐患，因此，请特别注意。移步后面的 URL 查看生成的强密码的",-1)),e(i,{href:"https://www.2daygeek.com/how-to-check-password-complexity-strength-and-score-in-linux/"},{default:n(()=>[...s[3]||(s[3]=[a("密码长度和分值",-1)])]),_:1}),s[5]||(s[5]=a("。本文将教你在 Linux 中如何实现最安全的策略。",-1))]),s[22]||(s[22]=r(`<p>在大多数 Linux 系统中，我们可以用 PAM（<ruby>可插拔认证模块<rt>pluggable authentication module</rt></ruby>）来加强密码策略。在下面的路径可以找到这个文件。</p><ul><li>在红帽系列的系统中，路径：<code>/etc/pam.d/system-auth</code>。</li><li>Debian 系列的系统中，路径：<code>/etc/pam.d/common-password</code>。</li></ul><p>关于默认的密码过期时间，可以在 <code>/etc/login.defs</code> 文件中查看详细信息。</p><p>为了更好理解，我摘取了文件的部分内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_MAX_DAYS   99999</span></span>
<span class="line"><span>PASS_MIN_DAYS   0</span></span>
<span class="line"><span>PASS_MIN_LEN    5</span></span>
<span class="line"><span>PASS_WARN_AGE   7</span></span></code></pre></div><p>详细解释:</p><ul><li><code>PASS_MAX_DAYS</code>：一个密码可使用的最大天数。</li><li><code>PASS_MIN_DAYS</code>：两次密码修改之间最小的间隔天数。</li><li><code>PASS_MIN_LEN</code>：密码最小长度。</li><li><code>PASS_WARN_AGE</code>：密码过期前给出警告的天数。</li></ul><p>我们将会展示在 Linux 中如何实现下面的 11 个密码策略。</p><ul><li>一个密码可使用的最大天数</li><li>两次密码修改之间最小的间隔天数</li><li>密码过期前给出警告的天数</li><li>密码历史记录/拒绝重复使用密码</li><li>密码最小长度</li><li>最少的大写字母个数</li><li>最少的小写字母个数</li><li>最少的数字个数</li><li>最少的其他字符（符号）个数</li><li>账号锁定 — 重试</li><li>账号解锁时间</li></ul><h3 id="密码可使用的最大天数是什么" tabindex="-1">密码可使用的最大天数是什么？ <a class="header-anchor" href="#密码可使用的最大天数是什么" aria-label="Permalink to “密码可使用的最大天数是什么？”">​</a></h3><p>这一参数限制一个密码可使用的最大天数。它强制用户在过期前修改他/她的密码。如果他们忘记修改，那么他们会登录不了系统。他们需要联系管理员才能正常登录。这个参数可以在 <code>/etc/login.defs</code> 文件中设置。我把这个参数设置为 90 天。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_MAX_DAYS   90</span></span></code></pre></div><h3 id="密码最小天数是什么" tabindex="-1">密码最小天数是什么？ <a class="header-anchor" href="#密码最小天数是什么" aria-label="Permalink to “密码最小天数是什么？”">​</a></h3><p>这个参数限制两次修改之间的最少天数。举例来说，如果这个参数被设置为 15 天，用户今天修改了密码，那么在 15 天之内他都不能修改密码。这个参数可以在 <code>/etc/login.defs</code> 文件中设置。我设置为 15 天。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_MIN_DAYS   15</span></span></code></pre></div><h3 id="密码警告天数是什么" tabindex="-1">密码警告天数是什么？ <a class="header-anchor" href="#密码警告天数是什么" aria-label="Permalink to “密码警告天数是什么？”">​</a></h3><p>这个参数控制密码警告的前置天数，在密码即将过期时会给用户警告提示。在警告天数结束前，用户会收到日常警告提示。这可以提醒用户在密码过期前修改他们的密码，否则我们就需要联系管理员来解锁密码。这个参数可以在 <code>/etc/login.defs</code> 文件中设置。我设置为 10 天。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_WARN_AGE   10</span></span></code></pre></div><p><strong>注意:</strong> 上面的所有参数仅对新账号有效，对已存在的账号无效。</p><h3 id="密码历史或拒绝重复使用密码是什么" tabindex="-1">密码历史或拒绝重复使用密码是什么？ <a class="header-anchor" href="#密码历史或拒绝重复使用密码是什么" aria-label="Permalink to “密码历史或拒绝重复使用密码是什么？”">​</a></h3><p>这个参数控制密码历史。它记录曾经使用过的密码（禁止使用的曾用密码的个数）。当用户设置新的密码时，它会检查密码历史，如果他们要设置的密码是一个曾经使用过的旧密码，将会发出警告提示。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。我设置密码历史为 5。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password  sufficient  pam_unix.so md5 shadow nullok try_first_pass use_authtok remember=5</span></span></code></pre></div><h3 id="密码最小长度是什么" tabindex="-1">密码最小长度是什么？ <a class="header-anchor" href="#密码最小长度是什么" aria-label="Permalink to “密码最小长度是什么？”">​</a></h3><p>这个参数表示密码的最小长度。当用户设置新密码时，系统会检查这个参数，如果新设的密码长度小于这个参数设置的值，会收到警告提示。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。我设置最小密码长度为 12。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password  requisite   pam_cracklib.so try_first_pass retry=3 minlen=12</span></span></code></pre></div><p><code>try_first_pass retry=3</code>：在密码设置交互界面，用户有 3 次机会重设密码。</p><h3 id="设置最少的大写字母个数" tabindex="-1">设置最少的大写字母个数？ <a class="header-anchor" href="#设置最少的大写字母个数" aria-label="Permalink to “设置最少的大写字母个数？”">​</a></h3><p>这个参数表示密码中至少需要的大写字母的个数。这些是密码强度参数，可以让密码更健壮。当用户设置新密码时，系统会检查这个参数，如果密码中没有大写字母，会收到警告提示。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。我设置密码（中的大写字母）的最小长度为 1 个字母。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password   requisite   pam_cracklib.so try_first_pass retry=3 minlen=12 ucredit=-1</span></span></code></pre></div><h3 id="设置最少的小写字母个数" tabindex="-1">设置最少的小写字母个数？ <a class="header-anchor" href="#设置最少的小写字母个数" aria-label="Permalink to “设置最少的小写字母个数？”">​</a></h3><p>这个参数表示密码中至少需要的小写字母的个数。这些是密码强度参数，可以让密码更健壮。当用户设置新密码时，系统会检查这个参数，如果密码中没有小写字母，会收到警告提示。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。我设置为 1 个字母。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password    requisite     pam_cracklib.so try_first_pass retry=3 minlen=12 lcredit=-1</span></span></code></pre></div><h3 id="设置密码中最少的数字个数" tabindex="-1">设置密码中最少的数字个数？ <a class="header-anchor" href="#设置密码中最少的数字个数" aria-label="Permalink to “设置密码中最少的数字个数？”">​</a></h3><p>这个参数表示密码中至少需要的数字的个数。这些是密码强度参数，可以让密码更健壮。当用户设置新密码时，系统会检查这个参数，如果密码中没有数字，会收到警告提示。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。我设置为 1 个数字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password    requisite     pam_cracklib.so try_first_pass retry=3 minlen=12 dcredit=-1</span></span></code></pre></div><h3 id="设置密码中最少的其他字符-符号-个数" tabindex="-1">设置密码中最少的其他字符（符号）个数？ <a class="header-anchor" href="#设置密码中最少的其他字符-符号-个数" aria-label="Permalink to “设置密码中最少的其他字符（符号）个数？”">​</a></h3><p>这个参数表示密码中至少需要的特殊符号的个数。这些是密码强度参数，可以让密码更健壮。当用户设置新密码时，系统会检查这个参数，如果密码中没有特殊符号，会收到警告提示。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。我设置为 1 个字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password    requisite     pam_cracklib.so try_first_pass retry=3 minlen=12 ocredit=-1</span></span></code></pre></div><h3 id="设置账号锁定" tabindex="-1">设置账号锁定？ <a class="header-anchor" href="#设置账号锁定" aria-label="Permalink to “设置账号锁定？”">​</a></h3><p>这个参数控制用户连续登录失败的最大次数。当达到设定的连续失败登录次数阈值时，锁定账号。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auth        required      pam_tally2.so onerr=fail audit silent deny=5</span></span>
<span class="line"><span>account required pam_tally2.so</span></span></code></pre></div><h3 id="设定账号解锁时间" tabindex="-1">设定账号解锁时间？ <a class="header-anchor" href="#设定账号解锁时间" aria-label="Permalink to “设定账号解锁时间？”">​</a></h3><p>这个参数表示用户解锁时间。如果一个用户账号在连续认证失败后被锁定了，当过了设定的解锁时间后，才会解锁。设置被锁定中的账号的解锁时间（900 秒 = 15分钟）。这个参数可以在 <code>/etc/pam.d/system-auth</code> 文件中设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auth        required      pam_tally2.so onerr=fail audit silent deny=5 unlock_time=900</span></span>
<span class="line"><span>account required pam_tally2.so</span></span></code></pre></div><hr>`,45)),t("p",null,[s[7]||(s[7]=a("via: ",-1)),e(i,{href:"https://www.2daygeek.com/how-to-set-password-complexity-policy-on-linux/"},{default:n(()=>[...s[6]||(s[6]=[a("https://www.2daygeek.com/how-to-set-password-complexity-policy-on-linux/",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("作者：",-1)),e(i,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...s[8]||(s[8]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[13]||(s[13]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 译者：",-1)),e(i,{href:"https://github.com/lxbwolf"},{default:n(()=>[...s[10]||(s[10]=[a("lxbwolf",-1)])]),_:1}),s[15]||(s[15]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[a("Linux中国",-1)])]),_:1}),s[20]||(s[20]=a(" 荣誉推出",-1))])])}const w=l(h,[["render",c]]);export{x as __pageData,w as default};
